  const dispositionAgent = compact ? createCompactAgent() : createDispositionAgent();
  const intakeAgent = createIntakeAgent();
  const historyAgent = createHistoryAgent(options.profile === "haiku-opus" ? FAST_MODEL : MODEL);
  const emergencyAgent = createEmergencyAgent();
  const reserve = () => options.budget === "nasal-verify" ? reserveNasalVerificationRun(options.budgetDirectory ?? join(directory, "nasal-verification-budget-v1")) : options.budget === "nasal" ? reserveNasalRun(options.budgetDirectory ?? join(directory, "nasal-budget-v1")) : options.budget === "compact" ? reserveCompactRun(options.budgetDirectory ?? join(directory, "compact-budget-v1")) : options.budget === "latency" ? reserveLatencyRun(options.budgetDirectory ?? join(directory, "budget")) : reserveInteractiveRun(options.budgetDirectory ?? join(directory, "interactive-budget-v1"));
